/* Banco de questões — estilo Instituto Mais (4 alternativas). t = tag da matéria; a = índice da resposta certa (0-3) */
window.QUESTOES = [
  // ================= CONTABILIDADE GERAL =================
  { t: 'cgeral', q: 'Segundo o método das partidas dobradas, em todo lançamento contábil:', o: ['o valor dos débitos deve ser igual ao valor dos créditos.', 'o débito deve ser sempre superior ao crédito.', 'só pode haver uma conta debitada e uma creditada.', 'as contas de resultado nunca são movimentadas.'], a: 0, e: 'Não há débito sem crédito de igual valor. Podem existir vários débitos e créditos (2ª, 3ª e 4ª fórmulas), mas as somas devem ser iguais.' },
  { t: 'cgeral', q: 'As contas que têm seu saldo AUMENTADO por lançamentos a DÉBITO são:', o: ['passivo e patrimônio líquido.', 'ativo e despesa.', 'receita e passivo.', 'patrimônio líquido e receita.'], a: 1, e: 'Ativo e despesa aumentam a débito; passivo, PL e receita aumentam a crédito.' },
  { t: 'cgeral', q: 'Uma empresa tem Ativo de R$ 500.000 e Passivo (obrigações) de R$ 320.000. Seu Patrimônio Líquido é de:', o: ['R$ 820.000.', 'R$ 500.000.', 'R$ 180.000.', 'R$ 320.000.'], a: 2, e: 'PL = Ativo − Passivo = 500.000 − 320.000 = 180.000.' },
  { t: 'cgeral', q: 'A compra de mercadorias à vista, em dinheiro, é um fato contábil:', o: ['modificativo aumentativo.', 'modificativo diminutivo.', 'misto aumentativo.', 'permutativo.'], a: 3, e: 'Troca um ativo (caixa) por outro (estoque). O PL não se altera: fato permutativo.' },
  { t: 'cgeral', q: 'O pagamento de salários do mês, em dinheiro, caracteriza fato contábil:', o: ['permutativo.', 'modificativo diminutivo.', 'modificativo aumentativo.', 'misto aumentativo.'], a: 1, e: 'Sai dinheiro (ativo) e se reconhece despesa, reduzindo o PL. É modificativo diminutivo.' },
  { t: 'cgeral', q: 'O recebimento de uma duplicata de R$ 1.000 acrescida de juros de R$ 50 é um fato contábil:', o: ['misto aumentativo.', 'misto diminutivo.', 'permutativo.', 'modificativo diminutivo.'], a: 0, e: 'Há permuta (duplicata vira caixa) e também receita de juros, que aumenta o PL: misto aumentativo.' },
  { t: 'cgeral', q: 'A conta "Perdas Estimadas em Créditos de Liquidação Duvidosa" (PECLD, antiga PDD) é classificada como:', o: ['passivo circulante.', 'despesa antecipada.', 'conta redutora do ativo.', 'reserva do patrimônio líquido.'], a: 2, e: 'A PECLD reduz o saldo de Clientes/Duplicatas a Receber no ativo. A contrapartida da constituição é uma despesa.' },
  { t: 'cgeral', q: 'Assinale a alternativa que diferencia corretamente reserva de provisão:', o: ['Reserva é passivo de valor incerto; provisão é parte do PL.', 'Reserva é parte do patrimônio líquido; provisão é um passivo de prazo ou valor incerto.', 'Ambas são contas do ativo.', 'Ambas são contas de resultado.'], a: 1, e: 'Reservas (de lucros, de capital) integram o PL. Provisões são obrigações presentes com prazo ou valor incertos (ex.: provisão para contingências).' },
  { t: 'cgeral', q: 'A perda de valor de um software adquirido pela empresa, ao longo de sua vida útil, é registrada como:', o: ['depreciação.', 'exaustão.', 'amortização.', 'provisão.'], a: 2, e: 'Depreciação: bens tangíveis. Amortização: intangíveis (software, marcas, patentes). Exaustão: recursos naturais.' },
  { t: 'cgeral', q: 'A redução do valor de uma jazida mineral à medida que o minério é extraído chama-se:', o: ['amortização.', 'exaustão.', 'depreciação.', 'impairment.'], a: 1, e: 'Exaustão aplica-se a recursos naturais esgotáveis (minas, florestas, poços).' },
  { t: 'cgeral', q: 'Um veículo custou R$ 50.000, tem valor residual de R$ 5.000 e vida útil de 5 anos. Pelo método linear, a depreciação anual é de:', o: ['R$ 10.000.', 'R$ 11.000.', 'R$ 5.000.', 'R$ 9.000.'], a: 3, e: '(50.000 − 5.000) ÷ 5 = 9.000 por ano.' },
  { t: 'cgeral', q: 'Entre os bens abaixo, NÃO sofre depreciação:', o: ['terrenos.', 'veículos.', 'máquinas.', 'móveis e utensílios.'], a: 0, e: 'Terrenos não têm vida útil definida, portanto não depreciam. Obras de arte também não.' },
  { t: 'cgeral', q: 'A conta "Depreciação Acumulada" é:', o: ['uma despesa do exercício.', 'uma conta do passivo não circulante.', 'uma conta redutora do ativo imobilizado.', 'uma reserva de lucros.'], a: 2, e: 'A Depreciação Acumulada reduz o custo do imobilizado. A despesa do período é "Despesa de Depreciação", conta de resultado.' },
  { t: 'cgeral', q: 'No desconto de duplicatas em banco, os juros cobrados antecipadamente são registrados em:', o: ['receita financeira do período.', 'conta redutora do passivo (encargos financeiros a apropriar), apropriados ao resultado pelo prazo.', 'conta do ativo imobilizado.', 'reserva de capital.'], a: 1, e: 'A duplicata descontada gera um passivo (obrigação com o banco); os juros antecipados ficam em conta redutora desse passivo e vão para despesa financeira conforme o prazo transcorre.' },
  { t: 'cgeral', q: 'Em um empréstimo bancário pré-fixado, os juros a transcorrer são contabilizados como:', o: ['despesa integral no momento da contratação.', 'receita diferida.', 'conta redutora do passivo, apropriada ao resultado pela competência.', 'ativo intangível.'], a: 2, e: 'Os encargos financeiros a apropriar reduzem o passivo e são reconhecidos como despesa mês a mês (regime de competência).' },
  { t: 'cgeral', q: 'Um lançamento com um débito e dois créditos é de:', o: ['1ª fórmula.', '2ª fórmula.', '3ª fórmula.', '4ª fórmula.'], a: 1, e: '1ª: 1 débito e 1 crédito. 2ª: 1 débito e vários créditos. 3ª: vários débitos e 1 crédito. 4ª: vários a vários.' },
  { t: 'cgeral', q: 'O aumento de capital social com integralização em dinheiro pelos sócios é um fato:', o: ['permutativo.', 'modificativo diminutivo.', 'modificativo aumentativo.', 'misto diminutivo.'], a: 2, e: 'Entra dinheiro (ativo) e aumenta o Capital Social (PL): o PL cresce, logo é modificativo aumentativo.' },
  { t: 'cgeral', q: 'Pelo regime de competência, as receitas e despesas são reconhecidas:', o: ['somente quando recebidas ou pagas.', 'no período em que ocorrem, independentemente do recebimento ou pagamento.', 'apenas no encerramento do exercício.', 'quando autorizadas pela administração.'], a: 1, e: 'Competência = reconhecer no período do fato gerador. Caixa = reconhecer no recebimento/pagamento.' },
  { t: 'cgeral', q: 'Vendas de R$ 100.000 com Custo das Mercadorias Vendidas de R$ 60.000 resultam em lucro bruto de:', o: ['R$ 160.000.', 'R$ 60.000.', 'R$ 40.000.', 'R$ 100.000.'], a: 2, e: 'Lucro bruto = Receita de vendas − CMV = 40.000.' },
  { t: 'cgeral', q: 'O balancete de verificação tem como principal finalidade:', o: ['apurar o lucro líquido do exercício.', 'verificar se a soma dos saldos devedores é igual à dos saldos credores.', 'calcular a depreciação do período.', 'substituir o balanço patrimonial.'], a: 1, e: 'O balancete confere a igualdade entre débitos e créditos (partidas dobradas). Não apura resultado nem substitui as demonstrações.' },

  // ================= CONTABILIDADE PÚBLICA / ORÇAMENTO =================
  { t: 'cpub', q: 'Segundo a Lei 4.320/64 (art. 2º), a Lei de Orçamento obedecerá aos princípios de:', o: ['unidade, universalidade e anualidade.', 'legalidade, impessoalidade e moralidade.', 'economicidade, eficiência e eficácia.', 'competência, prudência e oportunidade.'], a: 0, e: 'O art. 2º cita expressamente unidade, universalidade e anualidade.' },
  { t: 'cpub', q: 'O Plano Plurianual (PPA) tem vigência de:', o: ['1 ano.', '2 anos.', '4 anos.', '5 anos.'], a: 2, e: 'O PPA vale por 4 anos: do 2º ano do mandato até o 1º ano do mandato seguinte (CF, art. 165).' },
  { t: 'cpub', q: 'O princípio orçamentário segundo o qual a LOA não conterá dispositivo estranho à previsão da receita e à fixação da despesa é o da:', o: ['universalidade.', 'exclusividade.', 'anualidade.', 'não afetação.'], a: 1, e: 'Exclusividade. Exceções: autorização para abertura de créditos suplementares e contratação de operações de crédito, inclusive por antecipação de receita (ARO).' },
  { t: 'cpub', q: 'De acordo com a Lei 4.320/64, NÃO se consideram para fins do princípio da universalidade (não integram a receita orçamentária):', o: ['as receitas tributárias.', 'as transferências correntes.', 'as operações de crédito por antecipação da receita (ARO).', 'as receitas de alienação de bens.'], a: 2, e: 'Art. 3º, parágrafo único: não se consideram receita as operações de crédito por antecipação da receita, as emissões de papel-moeda e outras entradas compensatórias.' },
  { t: 'cpub', q: 'Pelo princípio do orçamento bruto (art. 6º da Lei 4.320/64):', o: ['as despesas podem ser compensadas com receitas da mesma natureza.', 'todas as receitas e despesas constarão da LOA pelos seus totais, vedadas quaisquer deduções.', 'só constam do orçamento as receitas líquidas.', 'as transferências constitucionais ficam fora do orçamento.'], a: 1, e: 'Orçamento bruto: valores pelos totais, sem deduções.' },
  { t: 'cpub', q: 'Conforme a Lei 4.320/64, a receita pública classifica-se, pela categoria econômica, em:', o: ['tributária e patrimonial.', 'orçamentária e extraorçamentária.', 'correntes e de capital.', 'ordinária e vinculada.'], a: 2, e: 'Art. 11: receitas correntes e receitas de capital. Orçamentária × extraorçamentária é outra classificação (quanto à natureza/pertencimento ao ente).' },
  { t: 'cpub', q: 'É receita de CAPITAL:', o: ['receita tributária.', 'receita patrimonial.', 'alienação de bens.', 'receita de serviços.'], a: 2, e: 'Receitas de capital: operações de crédito, alienação de bens, amortização de empréstimos, transferências de capital e outras receitas de capital.' },
  { t: 'cpub', q: 'São receitas CORRENTES, segundo o art. 11 da Lei 4.320/64:', o: ['operações de crédito e alienação de bens.', 'tributária, de contribuições, patrimonial, agropecuária, industrial, de serviços e transferências correntes.', 'amortização de empréstimos e transferências de capital.', 'apenas as receitas tributárias.'], a: 1, e: 'As receitas correntes são as da alternativa B, mais "outras receitas correntes".' },
  { t: 'cpub', q: 'A sequência correta dos estágios da receita pública é:', o: ['lançamento, previsão, arrecadação, recolhimento.', 'previsão, arrecadação, lançamento, recolhimento.', 'previsão, lançamento, arrecadação, recolhimento.', 'empenho, liquidação, arrecadação, pagamento.'], a: 2, e: 'Previsão → lançamento → arrecadação → recolhimento. Empenho, liquidação e pagamento são estágios da DESPESA.' },
  { t: 'cpub', q: 'O estágio da receita em que o contribuinte paga o tributo ao agente arrecadador (banco) é o(a):', o: ['lançamento.', 'arrecadação.', 'recolhimento.', 'previsão.'], a: 1, e: 'Arrecadação: pagamento pelo contribuinte aos agentes arrecadadores. Recolhimento: entrega do dinheiro pelos agentes ao Tesouro (unidade de tesouraria).' },
  { t: 'cpub', q: 'O art. 56 da Lei 4.320/64 determina que o recolhimento de todas as receitas observe o princípio da:', o: ['unidade de tesouraria, vedada a criação de caixas especiais.', 'exclusividade.', 'não afetação das receitas.', 'especificação.'], a: 0, e: 'Unidade de tesouraria (ou unidade de caixa): todas as receitas recolhidas a uma conta única, sem caixas especiais.' },
  { t: 'cpub', q: 'Segundo o art. 39 da Lei 4.320/64, a Dívida Ativa Tributária é o crédito da Fazenda Pública proveniente de:', o: ['aluguéis e foros não pagos.', 'obrigação legal relativa a tributos e respectivos adicionais e multas.', 'indenizações e restituições.', 'empréstimos concedidos a terceiros.'], a: 1, e: 'Dívida ativa tributária: tributos, adicionais e multas tributárias. Os demais créditos (aluguéis, foros, laudêmios, multas não tributárias, indenizações) são dívida ativa NÃO tributária.' },
  { t: 'cpub', q: 'Os créditos vencidos e não pagos, após apurada sua liquidez e certeza, são:', o: ['cancelados de ofício.', 'inscritos em dívida ativa.', 'registrados como despesa de exercícios anteriores.', 'incluídos em restos a pagar.'], a: 1, e: 'Inscrição em dívida ativa (art. 39). Restos a pagar e DEA são institutos da despesa.' },
  { t: 'cpub', q: 'De acordo com o art. 12 da Lei 4.320/64, as despesas CORRENTES subdividem-se em:', o: ['investimentos e inversões financeiras.', 'despesas de custeio e transferências correntes.', 'transferências de capital e investimentos.', 'pessoal e juros da dívida.'], a: 1, e: 'Correntes: despesas de custeio e transferências correntes. De capital: investimentos, inversões financeiras e transferências de capital.' },
  { t: 'cpub', q: 'A aquisição de um imóvel JÁ em utilização, para instalação de uma repartição, classifica-se como:', o: ['investimento.', 'despesa de custeio.', 'inversão financeira.', 'transferência de capital.'], a: 2, e: 'Inversão financeira: aquisição de imóveis ou bens de capital já em utilização, títulos de empresas já constituídas. Investimento: obras e bens NOVOS que aumentam o patrimônio.' },
  { t: 'cpub', q: 'A construção de uma escola e a compra de equipamentos e material permanente são classificadas como:', o: ['inversões financeiras.', 'investimentos.', 'despesas de custeio.', 'transferências correntes.'], a: 1, e: 'Investimentos: planejamento e execução de obras, aquisição de instalações, equipamentos e material permanente.' },
  { t: 'cpub', q: 'As "transferências", na Lei 4.320/64, são dotações para despesas:', o: ['com pessoal e encargos.', 'às quais não corresponda contraprestação direta em bens ou serviços.', 'de manutenção de serviços já criados.', 'com obras públicas.'], a: 1, e: 'Transferências (correntes ou de capital) são repasses sem contraprestação direta em bens ou serviços (ex.: subvenções, aposentadorias, auxílios).' },
  { t: 'cpub', q: 'A sequência dos estágios da despesa pública na fase de execução é:', o: ['liquidação, empenho, pagamento.', 'empenho, pagamento, liquidação.', 'empenho, liquidação, pagamento.', 'fixação, pagamento, liquidação.'], a: 2, e: 'Fixação (planejamento) → empenho → liquidação → pagamento.' },
  { t: 'cpub', q: 'Segundo o art. 58 da Lei 4.320/64, o empenho da despesa é:', o: ['o ato que verifica o direito adquirido pelo credor.', 'o despacho que determina que a despesa seja paga.', 'o ato emanado de autoridade competente que cria para o Estado obrigação de pagamento pendente ou não de implemento de condição.', 'a entrega de numerário ao credor.'], a: 2, e: 'Definição literal do art. 58. A alternativa A é a liquidação (art. 63) e a B é a ordem de pagamento (art. 64).' },
  { t: 'cpub', q: 'Nos termos do art. 60 da Lei 4.320/64:', o: ['é vedada a realização de despesa sem prévio empenho.', 'o empenho pode ser feito após o pagamento, em casos especiais.', 'a nota de empenho nunca pode ser dispensada.', 'a despesa pode ser paga antes da liquidação.'], a: 0, e: 'É vedada despesa sem prévio empenho. Em casos especiais pode-se dispensar a emissão da NOTA de empenho, nunca o empenho em si.' },
  { t: 'cpub', q: 'A liquidação da despesa (art. 63) tem por fim apurar:', o: ['apenas a dotação orçamentária disponível.', 'a origem e o objeto do que se deve pagar, a importância exata a pagar e a quem se deve pagar.', 'somente a regularidade fiscal do credor.', 'o excesso de arrecadação do exercício.'], a: 1, e: 'Liquidação = verificação do direito adquirido pelo credor, com base nos títulos e documentos comprobatórios.' },
  { t: 'cpub', q: 'O empenho utilizado para despesas cujo montante não se pode determinar previamente, como contas de água, luz e telefone, é o:', o: ['ordinário.', 'global.', 'estimativo.', 'especial.'], a: 2, e: 'Ordinário: valor exato, pago de uma vez. Estimativo: valor não determinável (água, luz). Global: despesas contratuais sujeitas a parcelamento (aluguéis).' },
  { t: 'cpub', q: 'O empenho GLOBAL é adequado para:', o: ['despesas de valor certo pagas de uma só vez.', 'despesas contratuais e outras sujeitas a parcelamento, como aluguéis.', 'despesas de exercícios anteriores.', 'despesas urgentes e imprevistas.'], a: 1, e: 'Empenho global (art. 60, §3º): despesas contratuais e outras sujeitas a parcelamento.' },
  { t: 'cpub', q: 'Segundo o art. 62 da Lei 4.320/64, o pagamento da despesa só será efetuado:', o: ['antes do empenho.', 'quando ordenado após sua regular liquidação.', 'após autorização do Legislativo.', 'no exercício seguinte.'], a: 1, e: 'Pagamento só após regular liquidação, mediante ordem de pagamento (despacho da autoridade competente, art. 64).' },
  { t: 'cpub', q: 'Consideram-se Restos a Pagar (art. 36 da Lei 4.320/64):', o: ['as despesas empenhadas mas não pagas até 31 de dezembro.', 'as receitas previstas e não arrecadadas.', 'as despesas pagas sem empenho.', 'as dívidas com exigibilidade superior a 12 meses.'], a: 0, e: 'RP = despesas empenhadas e não pagas até 31/12, distinguindo-se as processadas (liquidadas) das não processadas (só empenhadas).' },
  { t: 'cpub', q: 'Restos a pagar PROCESSADOS são aqueles:', o: ['apenas empenhados, ainda não liquidados.', 'empenhados e liquidados, mas não pagos.', 'pagos no exercício seguinte sem empenho.', 'cancelados por prescrição.'], a: 1, e: 'Processados = já passaram pela liquidação. Não processados = apenas empenhados.' },
  { t: 'cpub', q: 'Compõem a dívida flutuante (art. 92 da Lei 4.320/64), EXCETO:', o: ['os restos a pagar, excluídos os serviços da dívida.', 'os serviços da dívida a pagar.', 'os depósitos.', 'os empréstimos com exigibilidade superior a 12 meses.'], a: 3, e: 'Dívida flutuante: RP (exceto serviços da dívida), serviços da dívida a pagar, depósitos e débitos de tesouraria. Compromissos superiores a 12 meses são dívida FUNDADA (art. 98).' },
  { t: 'cpub', q: 'Podem ser pagas à conta de dotação específica do orçamento vigente, como Despesas de Exercícios Anteriores (art. 37):', o: ['quaisquer despesas do exercício atual.', 'despesas de exercícios encerrados para as quais o orçamento respectivo consignava crédito próprio, com saldo suficiente, que não se tenham processado na época própria.', 'restos a pagar processados.', 'despesas sem autorização orçamentária.'], a: 1, e: 'Também: restos a pagar com prescrição interrompida e compromissos reconhecidos após o encerramento do exercício.' },
  { t: 'cpub', q: 'Conforme o art. 35 da Lei 4.320/64, pertencem ao exercício financeiro:', o: ['as receitas nele previstas e as despesas nele pagas.', 'as receitas nele arrecadadas e as despesas nele legalmente empenhadas.', 'as receitas nele lançadas e as despesas nele liquidadas.', 'apenas as receitas e despesas pagas em dinheiro.'], a: 1, e: 'Receita pelo regime de caixa (arrecadação) e despesa pela competência (empenho): o chamado regime misto.' },
  { t: 'cpub', q: 'O exercício financeiro, segundo a Lei 4.320/64:', o: ['vai de julho a junho.', 'coincide com o ano civil.', 'é definido livremente por cada ente.', 'dura 4 anos, acompanhando o PPA.'], a: 1, e: 'Art. 34: o exercício financeiro coincidirá com o ano civil.' },
  { t: 'cpub', q: 'O regime de adiantamento (suprimento de fundos), previsto no art. 68 da Lei 4.320/64:', o: ['dispensa o empenho prévio.', 'aplica-se a despesas expressamente definidas em lei e consiste na entrega de numerário a servidor, sempre precedida de empenho.', 'pode ser concedido a servidor em alcance.', 'permite dois adiantamentos simultâneos ao mesmo servidor.'], a: 1, e: 'Art. 68 e 69: sempre precedido de empenho; vedado a servidor em alcance ou responsável por dois adiantamentos.' },
  { t: 'cpub', q: 'O crédito adicional destinado a reforço de dotação orçamentária já existente é o:', o: ['especial.', 'extraordinário.', 'suplementar.', 'ordinário.'], a: 2, e: 'Suplementar: reforço. Especial: despesa sem dotação específica. Extraordinário: urgente e imprevista (guerra, comoção intestina, calamidade).' },
  { t: 'cpub', q: 'Os créditos EXTRAORDINÁRIOS destinam-se a:', o: ['despesas para as quais não haja dotação específica.', 'reforço de dotação orçamentária.', 'despesas urgentes e imprevistas, em caso de guerra, comoção intestina ou calamidade pública.', 'pagamento de restos a pagar.'], a: 2, e: 'Art. 41, III. São abertos por decreto do Executivo, que dará imediato conhecimento ao Legislativo (art. 44).' },
  { t: 'cpub', q: 'Quanto à autorização e abertura, os créditos suplementares e especiais:', o: ['são abertos por lei e autorizados por decreto.', 'são autorizados por lei e abertos por decreto do Executivo.', 'independem de autorização legislativa.', 'são abertos por medida provisória em qualquer ente.'], a: 1, e: 'Art. 42: autorizados por lei e abertos por decreto. Os extraordinários dispensam autorização prévia por lei.' },
  { t: 'cpub', q: 'NÃO constitui fonte de recursos para abertura de créditos suplementares e especiais (art. 43):', o: ['superávit financeiro apurado em balanço patrimonial do exercício anterior.', 'excesso de arrecadação.', 'anulação parcial ou total de dotações.', 'déficit de arrecadação.'], a: 3, e: 'Fontes: superávit financeiro, excesso de arrecadação, anulação de dotações e produto de operações de crédito autorizadas.' },
  { t: 'cpub', q: 'O superávit financeiro, para fins de abertura de créditos adicionais, é:', o: ['a diferença entre receita prevista e arrecadada.', 'a diferença positiva entre o ativo financeiro e o passivo financeiro.', 'o total das receitas correntes do exercício.', 'o saldo da conta caixa em 31/12.'], a: 1, e: 'Art. 43, §2º: ativo financeiro − passivo financeiro, conjugando-se os saldos dos créditos adicionais transferidos e as operações de crédito a eles vinculadas.' },
  { t: 'cpub', q: 'O excesso de arrecadação, segundo a Lei 4.320/64, é:', o: ['o saldo positivo das diferenças acumuladas mês a mês entre a arrecadação prevista e a realizada, considerada a tendência do exercício.', 'qualquer receita extraorçamentária recebida.', 'o superávit do balanço patrimonial.', 'o valor dos restos a pagar cancelados.'], a: 0, e: 'Art. 43, §3º. Deduz-se ainda a importância dos créditos extraordinários abertos no exercício (§4º).' },
  { t: 'cpub', q: 'Os créditos adicionais têm vigência:', o: ['ilimitada.', 'adstrita ao exercício financeiro em que forem abertos, salvo disposição legal em contrário quanto aos especiais e extraordinários.', 'de 4 anos.', 'até o fim do mandato do chefe do Executivo.'], a: 1, e: 'Art. 45. Pela CF (art. 167, §2º), especiais e extraordinários autorizados nos últimos 4 meses do exercício podem ser reabertos nos limites de seus saldos.' },
  { t: 'cpub', q: 'Segundo o art. 105 da Lei 4.320/64, o Ativo Financeiro compreende:', o: ['os bens cuja alienação dependa de autorização legislativa.', 'os créditos e valores realizáveis independentemente de autorização orçamentária e os valores numerários.', 'as dívidas fundadas.', 'os compromissos exigíveis cujo pagamento independa de autorização orçamentária.'], a: 1, e: 'Ativo financeiro: realizável independentemente de autorização orçamentária + numerário. A alternativa A é ativo permanente; a D é passivo financeiro.' },
  { t: 'cpub', q: 'O Passivo Permanente, na Lei 4.320/64, compreende:', o: ['os restos a pagar.', 'os depósitos e cauções.', 'as dívidas fundadas e outras que dependam de autorização legislativa para amortização ou resgate.', 'os serviços da dívida a pagar.'], a: 2, e: 'Passivo financeiro: compromissos cujo pagamento independe de autorização orçamentária (RP, depósitos). Passivo permanente: dívida fundada e demais que dependem de autorização legislativa.' },
  { t: 'cpub', q: 'São demonstrações contábeis previstas no art. 101 da Lei 4.320/64:', o: ['Balanço Patrimonial, DRE, DFC e DMPL.', 'Balanço Orçamentário, Balanço Financeiro, Balanço Patrimonial e Demonstração das Variações Patrimoniais.', 'apenas Balanço Patrimonial e Balanço Orçamentário.', 'Balanço Social e DVA.'], a: 1, e: 'Os 4 balanços da Lei 4.320: Orçamentário, Financeiro, Patrimonial e DVP.' },
  { t: 'cpub', q: 'O Balanço Orçamentário demonstrará:', o: ['as variações do patrimônio.', 'as receitas e despesas previstas em confronto com as realizadas.', 'os ingressos e dispêndios extraorçamentários.', 'o saldo patrimonial.'], a: 1, e: 'Art. 102: previsto × realizado.' },
  { t: 'cpub', q: 'O Balanço Financeiro (art. 103) demonstra:', o: ['somente as receitas tributárias.', 'a receita e a despesa orçamentárias, os recebimentos e pagamentos extraorçamentários, conjugados com os saldos em espécie do exercício anterior e os que se transferem ao seguinte.', 'as receitas previstas em confronto com as realizadas.', 'o resultado patrimonial do exercício.'], a: 1, e: 'Os restos a pagar do exercício são computados na receita extraorçamentária para compensar sua inclusão na despesa orçamentária (parágrafo único).' },
  { t: 'cpub', q: 'A Demonstração das Variações Patrimoniais (DVP) evidencia:', o: ['as alterações verificadas no patrimônio, resultantes ou independentes da execução orçamentária, e indica o resultado patrimonial do exercício.', 'apenas as receitas e despesas orçamentárias.', 'o fluxo de caixa do exercício.', 'o confronto entre receita prevista e realizada.'], a: 0, e: 'Art. 104. Resultado patrimonial = variações aumentativas − variações diminutivas.' },
  { t: 'cpub', q: 'No Balanço Patrimonial da Lei 4.320/64 (art. 105), o Saldo Patrimonial corresponde a:', o: ['Ativo Financeiro − Passivo Financeiro.', 'Ativo Real (financeiro + permanente) − Passivo Real (financeiro + permanente).', 'Receita − Despesa.', 'Ativo Permanente − Ativo Financeiro.'], a: 1, e: 'Saldo patrimonial = ativo real líquido (ou passivo real a descoberto, quando negativo). Ativo financeiro − passivo financeiro é o superávit financeiro.' },
  { t: 'cpub', q: 'Os sistemas contábeis tradicionalmente associados à Lei 4.320/64 são:', o: ['orçamentário, financeiro, patrimonial e de compensação.', 'caixa, bancos e almoxarifado.', 'legal, gerencial e fiscal.', 'receita, despesa e resultado.'], a: 0, e: 'Orçamentário, financeiro, patrimonial e compensação. O MCASP atual estrutura a contabilidade em subsistemas: orçamentário, patrimonial, custos e compensação.' },
  { t: 'cpub', q: 'As garantias e contragarantias recebidas e os contratos assinados, que podem vir a afetar o patrimônio, são registrados no sistema:', o: ['orçamentário.', 'financeiro.', 'de compensação.', 'patrimonial.'], a: 2, e: 'Compensação: atos potenciais (ativos e passivos), que podem vir a afetar o patrimônio.' },
  { t: 'cpub', q: 'Segundo o art. 75 da Lei 4.320/64, o controle da execução orçamentária compreende, entre outros:', o: ['apenas a legalidade dos atos de arrecadação.', 'a legalidade dos atos de arrecadação e realização da despesa, a fidelidade funcional dos agentes responsáveis por bens e valores e o cumprimento do programa de trabalho.', 'somente a auditoria das contas bancárias.', 'a aprovação da LOA pelo Legislativo.'], a: 1, e: 'Os três aspectos do art. 75: legalidade, fidelidade funcional e cumprimento do programa de trabalho (em termos monetários e de obras e serviços).' },
  { t: 'cpub', q: 'No município, o controle EXTERNO da execução orçamentária é exercido:', o: ['pelo Prefeito.', 'pela Câmara Municipal, com auxílio do Tribunal de Contas (em SP, o TCE-SP).', 'pelo Ministério da Fazenda.', 'pela controladoria interna da Prefeitura.'], a: 1, e: 'Controle interno: o próprio Poder (art. 76). Externo: Legislativo com auxílio do Tribunal de Contas (art. 81; CF art. 31).' },
  { t: 'cpub', q: 'O pagamento de uma caução devolvida ao fornecedor ao final do contrato é exemplo de:', o: ['despesa orçamentária corrente.', 'despesa orçamentária de capital.', 'despesa extraorçamentária.', 'inversão financeira.'], a: 2, e: 'Cauções, depósitos e consignações são ingressos extraorçamentários; sua devolução é despesa extraorçamentária (não precisa de autorização orçamentária).' },
  { t: 'cpub', q: 'A receita tributária é composta por:', o: ['impostos, taxas e contribuições de melhoria.', 'aluguéis, juros e dividendos.', 'operações de crédito e alienação de bens.', 'multas e indenizações.'], a: 0, e: 'Tributos (CTN art. 5º): impostos, taxas e contribuições de melhoria. Aluguéis, juros e dividendos são receita patrimonial.' },
  { t: 'cpub', q: 'As operações de crédito por antecipação de receita orçamentária (ARO) são classificadas como:', o: ['receita de capital.', 'receita corrente.', 'receita extraorçamentária.', 'transferência de capital.'], a: 2, e: 'A ARO é um empréstimo de curto prazo para cobrir insuficiência de caixa, não é receita orçamentária (art. 3º, parágrafo único da Lei 4.320).' },
  { t: 'cpub', q: 'Na DVP, o resultado patrimonial do exercício é obtido por:', o: ['receita orçamentária − despesa orçamentária.', 'variações patrimoniais aumentativas − variações patrimoniais diminutivas.', 'ativo financeiro − passivo financeiro.', 'receita prevista − receita realizada.'], a: 1, e: 'VPA − VPD = resultado patrimonial (superávit ou déficit patrimonial).' },
  { t: 'cpub', q: 'O princípio da anualidade (ou periodicidade) orçamentária significa que:', o: ['o orçamento vigora por quatro anos.', 'o orçamento tem vigência limitada a um exercício financeiro, que coincide com o ano civil.', 'as receitas devem ser estimadas a cada mês.', 'o orçamento só pode ser alterado uma vez por ano.'], a: 1, e: 'Anualidade: vigência de um exercício (1º/01 a 31/12).' },
  { t: 'cpub', q: 'O princípio orçamentário da NÃO AFETAÇÃO (CF, art. 167, IV) veda:', o: ['a vinculação da receita de impostos a órgão, fundo ou despesa, ressalvadas as exceções constitucionais.', 'a realização de despesa sem empenho.', 'a abertura de créditos extraordinários.', 'a vinculação de taxas a serviços.'], a: 0, e: 'Aplica-se a IMPOSTOS. Exceções: saúde, educação, repartição constitucional, garantias etc.' },
  { t: 'cpub', q: 'A inscrição de restos a pagar não processados ocorre quando a despesa:', o: ['foi empenhada e liquidada, mas não paga.', 'foi apenas empenhada, sem liquidação, até 31/12.', 'foi paga sem empenho.', 'foi prevista mas não fixada.'], a: 1, e: 'Não processados: só empenhados. Processados: liquidados e não pagos.' },
  { t: 'cpub', q: 'A Lei de Diretrizes Orçamentárias (LDO):', o: ['tem vigência de 4 anos.', 'estabelece metas e prioridades da administração e orienta a elaboração da LOA.', 'substitui a LOA nos anos de eleição.', 'é aprovada por decreto do Executivo.'], a: 1, e: 'LDO: anual, orienta a elaboração da LOA, trata de alterações tributárias e, pela LRF, traz Anexo de Metas e Anexo de Riscos Fiscais.' },

  // ================= LRF =================
  { t: 'lrf', q: 'Segundo a LRF, no município, a despesa total com pessoal NÃO poderá exceder:', o: ['50% da receita corrente líquida.', '60% da receita corrente líquida.', '70% da receita corrente líquida.', '54% da receita corrente líquida.'], a: 1, e: 'Art. 19: União 50%, Estados 60%, Municípios 60%. No município, 54% para o Executivo e 6% para o Legislativo (incluído o TCM, se houver).' },
  { t: 'lrf', q: 'Na repartição dos limites de despesa com pessoal do município (art. 20 da LRF), cabem:', o: ['50% ao Executivo e 10% ao Legislativo.', '54% ao Executivo e 6% ao Legislativo.', '55% ao Executivo e 5% ao Legislativo.', '60% ao Executivo e 0% ao Legislativo.'], a: 1, e: 'Executivo 54% e Legislativo 6% (incluído o Tribunal de Contas do Município, quando houver).' },
  { t: 'lrf', q: 'O chamado limite PRUDENCIAL de despesa com pessoal corresponde a:', o: ['90% do limite legal.', '95% do limite legal.', '100% do limite legal.', '80% do limite legal.'], a: 1, e: 'Prudencial: 95% do limite (art. 22, parágrafo único), com vedações como criar cargo, alterar carreira e prover cargos. O alerta do Tribunal de Contas é dado aos 90% (art. 59, §1º, II).' },
  { t: 'lrf', q: 'Ultrapassado o limite de despesa com pessoal, o percentual excedente deverá ser eliminado:', o: ['no exercício seguinte.', 'nos dois quadrimestres seguintes, sendo pelo menos um terço no primeiro.', 'em 30 dias.', 'nos quatro anos seguintes.'], a: 1, e: 'Art. 23 da LRF.' },
  { t: 'lrf', q: 'A Receita Corrente Líquida (RCL) do município é o somatório das receitas correntes, deduzidas:', o: ['todas as transferências recebidas da União.', 'a contribuição dos servidores para o custeio do RPPS e as receitas de compensação financeira entre regimes.', 'as despesas de custeio.', 'as receitas de capital.'], a: 1, e: 'Art. 2º, IV, "c". A RCL é apurada somando-se as receitas do mês de referência e dos 11 anteriores.' },
  { t: 'lrf', q: 'O Relatório Resumido da Execução Orçamentária (RREO) deve ser publicado:', o: ['até 30 dias após o encerramento de cada bimestre.', 'até 30 dias após o encerramento de cada quadrimestre.', 'anualmente.', 'semestralmente, em qualquer município.'], a: 0, e: 'RREO: bimestral (art. 52). RGF: quadrimestral (art. 55), podendo ser semestral em municípios com menos de 50 mil habitantes (art. 63).' },
  { t: 'lrf', q: 'O Relatório de Gestão Fiscal (RGF) é emitido:', o: ['ao final de cada bimestre.', 'ao final de cada quadrimestre, pelos titulares dos Poderes e órgãos.', 'apenas ao final do exercício.', 'ao final de cada mês.'], a: 1, e: 'Art. 54 e 55: quadrimestral, publicado até 30 dias após o encerramento do período. Municípios com menos de 50 mil habitantes podem optar pela divulgação semestral.' },
  { t: 'lrf', q: 'Constitui renúncia de receita, nos termos do art. 14 da LRF:', o: ['a arrecadação de taxas.', 'a anistia, remissão, subsídio, crédito presumido, isenção em caráter não geral e alteração de alíquota que implique redução discriminada de tributos.', 'a cobrança de dívida ativa.', 'o aumento de alíquota do IPTU.'], a: 1, e: 'A renúncia exige estimativa de impacto orçamentário-financeiro e medidas de compensação (ou demonstração de que não afeta as metas fiscais).' },
  { t: 'lrf', q: 'Segundo a LRF, é NULO DE PLENO DIREITO o ato que resulte aumento da despesa com pessoal expedido:', o: ['nos 90 dias anteriores ao final do mandato.', 'nos 180 dias anteriores ao final do mandato do titular do Poder ou órgão.', 'no primeiro ano do mandato.', 'em ano de eleição, a qualquer tempo.'], a: 1, e: 'Art. 21 da LRF: 180 dias anteriores ao final do mandato.' },
  { t: 'lrf', q: 'Integram a Lei de Diretrizes Orçamentárias, por exigência da LRF:', o: ['o Anexo de Metas Fiscais e o Anexo de Riscos Fiscais.', 'o Balanço Patrimonial e a DVP.', 'o RREO e o RGF.', 'o PPA e a LOA.'], a: 0, e: 'Art. 4º, §§1º e 3º da LRF.' },
  { t: 'lrf', q: 'Considera-se despesa obrigatória de caráter continuado (art. 17 da LRF) a despesa corrente derivada de lei, medida provisória ou ato normativo que fixe obrigação legal de sua execução por período superior a:', o: ['um exercício.', 'dois exercícios.', 'quatro exercícios.', 'seis meses.'], a: 1, e: 'Superior a dois exercícios.' },
  { t: 'lrf', q: 'São instrumentos de transparência da gestão fiscal, conforme o art. 48 da LRF:', o: ['apenas o balanço patrimonial.', 'planos, orçamentos, LDO, prestações de contas e parecer prévio, RREO e RGF, com ampla divulgação, inclusive em meios eletrônicos.', 'somente os relatórios enviados ao Tribunal de Contas.', 'as notas de empenho.'], a: 1, e: 'Inclui também incentivo à participação popular e audiências públicas na elaboração dos planos e orçamentos.' },
  { t: 'lrf', q: 'Para a despesa com pessoal, a LRF considera o somatório dos gastos com ativos, inativos e pensionistas, apurado:', o: ['no mês de referência apenas.', 'somando-se a realizada no mês em referência com as dos onze imediatamente anteriores, pelo regime de competência.', 'por estimativa anual.', 'somente no último mês do exercício.'], a: 1, e: 'Art. 18, §2º. Contratos de terceirização que substituem servidores são contabilizados como "Outras Despesas de Pessoal".' },
  { t: 'lrf', q: 'A operação de crédito por antecipação de receita (ARO), pela LRF (art. 38):', o: ['pode ser realizada a qualquer tempo, inclusive no último ano de mandato.', 'deve ser liquidada, com juros e encargos, até o dia 10 de dezembro de cada ano e é proibida no último ano do mandato.', 'não precisa ser liquidada no mesmo exercício.', 'é considerada receita orçamentária corrente.'], a: 1, e: 'Liquidação até 10/12; proibida no último ano de mandato e enquanto houver outra ARO não resgatada.' },
  { t: 'lrf', q: 'O limite de ALERTA emitido pelo Tribunal de Contas quando a despesa com pessoal se aproxima do limite ocorre quando ela ultrapassa:', o: ['80% do limite.', '90% do limite.', '95% do limite.', '100% do limite.'], a: 1, e: 'Alerta: 90% (art. 59, §1º, II). Prudencial: 95% (art. 22). Máximo: 100% (art. 20).' },

  // ================= RPPS / SSPREV =================
  { t: 'rpps', q: 'O Regime Próprio de Previdência Social (RPPS) destina-se:', o: ['a todos os trabalhadores do município, inclusive da iniciativa privada.', 'exclusivamente aos servidores titulares de cargo efetivo.', 'aos servidores comissionados e temporários.', 'aos vereadores e ao prefeito, apenas.'], a: 1, e: 'CF art. 40: servidores titulares de cargo efetivo. Comissionados, temporários e empregados públicos vinculam-se ao RGPS.' },
  { t: 'rpps', q: 'De acordo com a Lei 9.717/98 (art. 2º), a contribuição do ente federativo ao RPPS:', o: ['é livre, sem limites.', 'não poderá ser inferior ao valor da contribuição do servidor ativo nem superior ao dobro desta.', 'deve ser igual à metade da contribuição do servidor.', 'é dispensada quando o regime for superavitário.'], a: 1, e: 'Piso: igual à contribuição do servidor. Teto: o dobro.' },
  { t: 'rpps', q: 'Entre as regras da Lei 9.717/98 para organização dos RPPS, inclui-se:', o: ['a dispensa de avaliação atuarial.', 'a possibilidade de empréstimo dos recursos ao próprio ente.', 'o equilíbrio financeiro e atuarial, com avaliação atuarial inicial e em cada balanço.', 'a cobertura de benefícios distintos dos do RGPS, sem restrição.'], a: 2, e: 'Art. 1º: caráter contributivo, equilíbrio financeiro e atuarial, avaliação atuarial, registro contábil individualizado, pleno acesso às informações.' },
  { t: 'rpps', q: 'A Lei 9.717/98 VEDA, em relação aos recursos do RPPS:', o: ['a aplicação em títulos do Governo Federal.', 'a utilização para empréstimos de qualquer natureza, inclusive ao ente, a entidades da administração indireta e aos segurados.', 'o pagamento de aposentadorias.', 'a avaliação atuarial anual.'], a: 1, e: 'Também é vedada a aplicação em títulos públicos que não sejam do Governo Federal.' },
  { t: 'rpps', q: 'Após a Emenda Constitucional 103/2019, o RPPS pode conceder como benefícios:', o: ['aposentadorias, pensão por morte, auxílio-doença e salário-família.', 'apenas aposentadorias e pensão por morte.', 'apenas aposentadoria por invalidez.', 'qualquer benefício previsto em lei municipal.'], a: 1, e: 'Os afastamentos por incapacidade temporária, salário-maternidade, salário-família e auxílio-reclusão passaram a ser pagos pelo ente (tesouro), não pelo RPPS.' },
  { t: 'rpps', q: 'O RPPS caracteriza-se por ter caráter:', o: ['facultativo e não contributivo.', 'contributivo e solidário, mediante contribuição do ente, dos servidores ativos, aposentados e pensionistas.', 'exclusivamente privado.', 'assistencial, custeado só pelo ente.'], a: 1, e: 'CF art. 40, caput: regime contributivo e solidário.' },
  { t: 'rpps', q: 'O SSPREV, criado pela LC Municipal 241/2019, tem natureza jurídica de:', o: ['empresa pública.', 'sociedade de economia mista.', 'autarquia municipal, unidade gestora do RPPS de São Sebastião.', 'fundação privada.'], a: 2, e: 'A LC 241/2019 criou o SSPREV como autarquia (com autonomia administrativa e financeira) e reestruturou o FAPS. Ler a lei seca: estrutura, conselhos, diretoria e receitas.' },
  { t: 'rpps', q: 'Pela Constituição (art. 40, §20), cada ente federativo:', o: ['pode manter vários RPPS, um por Poder.', 'só pode ter um RPPS e uma unidade gestora, salvo para os militares.', 'deve filiar seus servidores efetivos ao RGPS.', 'pode criar um RPPS por secretaria.'], a: 1, e: 'Vedada a existência de mais de um RPPS e de mais de uma unidade gestora por ente (ressalvado o regime dos militares).' },
  { t: 'rpps', q: 'A fiscalização e a supervisão dos RPPS, em âmbito nacional, cabem:', o: ['ao Banco Central.', 'à União, por meio do Ministério da Previdência Social (Secretaria de Regime Próprio e Complementar), que emite o CRP.', 'ao Tribunal de Contas da União apenas.', 'ao INSS.'], a: 1, e: 'Lei 9.717, art. 9º. O Certificado de Regularidade Previdenciária (CRP) atesta o cumprimento das normas e é exigido para transferências voluntárias.' },
  { t: 'rpps', q: 'Em relação às receitas típicas de um instituto de previdência municipal como o SSPREV, é INCORRETO afirmar:', o: ['incluem as contribuições dos servidores ativos, aposentados e pensionistas.', 'incluem a contribuição patronal do município.', 'incluem os rendimentos das aplicações financeiras dos recursos.', 'incluem a arrecadação de IPTU e ISS do município.'], a: 3, e: 'IPTU e ISS são receitas tributárias do município, não do RPPS. O RPPS vive de contribuições (servidor + ente), compensação previdenciária e rendimentos das aplicações.' },

  // ================= LICITAÇÕES =================
  { t: 'lic', q: 'São modalidades de licitação previstas na Lei 14.133/2021:', o: ['concorrência, tomada de preços, convite, concurso e leilão.', 'pregão, concorrência, concurso, leilão e diálogo competitivo.', 'pregão, convite e tomada de preços.', 'concorrência, leilão e carta-convite.'], a: 1, e: 'Art. 28. Tomada de preços e convite deixaram de existir.' },
  { t: 'lic', q: 'O pregão é a modalidade obrigatória para aquisição de:', o: ['obras de engenharia de grande vulto.', 'bens e serviços comuns, cujos padrões de desempenho e qualidade possam ser objetivamente definidos no edital.', 'bens imóveis.', 'serviços técnicos de natureza predominantemente intelectual.'], a: 1, e: 'Art. 6º, XLI e art. 29. Critério de julgamento: menor preço ou maior desconto.' },
  { t: 'lic', q: 'A modalidade de licitação destinada à alienação de bens imóveis ou de bens móveis inservíveis ou legalmente apreendidos é o:', o: ['concurso.', 'pregão.', 'leilão.', 'diálogo competitivo.'], a: 2, e: 'Leilão: a quem oferecer o maior lance.' },
  { t: 'lic', q: 'O concurso, na Lei 14.133/2021, destina-se à:', o: ['compra de bens comuns.', 'escolha de trabalho técnico, científico ou artístico, mediante prêmio ou remuneração ao vencedor.', 'contratação de obras.', 'venda de bens inservíveis.'], a: 1, e: 'Critério de julgamento: melhor técnica ou conteúdo artístico.' },
  { t: 'lic', q: 'O diálogo competitivo é a modalidade em que a Administração:', o: ['compra bens comuns pelo menor preço.', 'realiza diálogos com licitantes previamente selecionados para desenvolver alternativas capazes de atender às suas necessidades (inovação, soluções técnicas).', 'aliena bens imóveis.', 'dispensa a licitação por emergência.'], a: 1, e: 'Art. 32. Conduzido por comissão de contratação com pelo menos 3 servidores efetivos.' },
  { t: 'lic', q: 'A diferença entre dispensa e inexigibilidade de licitação é que:', o: ['na dispensa a competição é inviável; na inexigibilidade a lei permite não licitar.', 'na dispensa a competição é possível, mas a lei permite não licitar; na inexigibilidade a competição é inviável.', 'não há diferença.', 'a inexigibilidade só se aplica a obras.'], a: 1, e: 'Dispensa: art. 75 (baixo valor, emergência etc.). Inexigibilidade: art. 74 (fornecedor exclusivo, artista consagrado, notória especialização).' },
  { t: 'lic', q: 'É hipótese de INEXIGIBILIDADE de licitação (art. 74 da Lei 14.133/2021):', o: ['contratação de pequeno valor para serviços de engenharia.', 'contratação em situação de emergência ou calamidade.', 'contratação de artista consagrado pela crítica especializada ou pela opinião pública, diretamente ou por empresário exclusivo.', 'contratação de remanescente de obra.'], a: 2, e: 'As demais são hipóteses de DISPENSA (art. 75).' },
  { t: 'lic', q: 'A ordem das fases do processo licitatório, segundo o art. 17 da Lei 14.133/2021, é:', o: ['habilitação, julgamento, propostas, homologação.', 'preparatória, divulgação do edital, apresentação de propostas e lances, julgamento, habilitação, recursal e homologação.', 'edital, habilitação, propostas, adjudicação.', 'propostas, habilitação, julgamento, edital.'], a: 1, e: 'Como regra, a habilitação vem DEPOIS do julgamento (inversão possível por ato motivado).' },
  { t: 'lic', q: 'NÃO é critério de julgamento previsto no art. 33 da Lei 14.133/2021:', o: ['menor preço.', 'maior desconto.', 'maior retorno econômico.', 'maior prazo de entrega.'], a: 3, e: 'Critérios: menor preço, maior desconto, melhor técnica ou conteúdo artístico, técnica e preço, maior lance, maior retorno econômico.' },
  { t: 'lic', q: 'Entre os princípios expressos no art. 5º da Lei 14.133/2021 estão:', o: ['sigilo absoluto e informalidade.', 'legalidade, impessoalidade, moralidade, publicidade, eficiência, planejamento, segregação de funções, vinculação ao edital e julgamento objetivo.', 'apenas legalidade e economicidade.', 'livre escolha do fornecedor pelo gestor.'], a: 1, e: 'A lista do art. 5º é longa: inclui ainda interesse público, probidade, igualdade, transparência, motivação, segurança jurídica, razoabilidade, competitividade, proporcionalidade, celeridade, economicidade e desenvolvimento nacional sustentável.' },
  { t: 'lic', q: 'As sanções administrativas previstas na Lei 14.133/2021 (art. 156) são:', o: ['advertência, multa, impedimento de licitar e contratar e declaração de inidoneidade.', 'prisão, multa e suspensão.', 'apenas multa.', 'advertência e demissão.'], a: 0, e: 'Impedimento: até 3 anos. Declaração de inidoneidade: de 3 a 6 anos.' },
  { t: 'lic', q: 'Os contratos de serviços e fornecimentos contínuos, pela Lei 14.133/2021, podem ter prazo de até:', o: ['12 meses, improrrogáveis.', '5 anos, prorrogáveis sucessivamente até 10 anos.', '2 anos.', '20 anos.'], a: 1, e: 'Art. 106 (até 5 anos) e art. 107 (prorrogação até 10 anos), desde que vantajoso e com previsão orçamentária.' },
  { t: 'lic', q: 'O Portal Nacional de Contratações Públicas (PNCP) tem a função de:', o: ['substituir os Tribunais de Contas.', 'divulgar centralizadamente os atos das contratações públicas (editais, contratos, atas) de todos os entes.', 'realizar os pagamentos aos fornecedores.', 'julgar recursos administrativos.'], a: 1, e: 'Art. 174. A publicação no PNCP é condição de eficácia dos contratos.' },
  { t: 'lic', q: 'Na Lei 14.133/2021, o pregão é conduzido por:', o: ['uma comissão de contratação com 5 membros.', 'um agente de contratação designado pregoeiro.', 'o chefe do Poder Executivo pessoalmente.', 'o Tribunal de Contas.'], a: 1, e: 'Art. 8º: agente de contratação (pregoeiro, no pregão). O diálogo competitivo exige comissão de contratação.' },

  // ================= LÍNGUA PORTUGUESA =================
  { t: 'port', q: 'Assinale a alternativa em que o uso da crase está CORRETO:', o: ['Fui à pé até a escola.', 'Entregou o documento à ela.', 'Refiro-me àquela proposta apresentada ontem.', 'Começou à trabalhar cedo.'], a: 2, e: 'Crase antes de "aquela" (a + aquela). Não há crase antes de palavra masculina (pé), pronome pessoal (ela) ou verbo (trabalhar).' },
  { t: 'port', q: 'Em qual alternativa há ERRO de concordância verbal?', o: ['Havia muitas pessoas na fila.', 'Faz dois anos que ele viajou.', 'Haviam muitos candidatos inscritos.', 'Existem vários motivos para estudar.'], a: 2, e: '"Haver" no sentido de existir é impessoal: fica no singular ("Havia muitos candidatos"). "Existir" é pessoal e concorda normalmente.' },
  { t: 'port', q: 'Assinale a frase CORRETA quanto à concordância nominal:', o: ['É proibido a entrada de estranhos.', 'É proibida entrada de estranhos.', 'É proibida a entrada de estranhos.', 'São proibido as entradas.'], a: 2, e: 'Com artigo determinando o substantivo, o adjetivo concorda: "é proibida a entrada". Sem artigo, fica invariável: "é proibido entrada".' },
  { t: 'port', q: 'Quanto à regência verbal, está CORRETA a frase:', o: ['Assisti o filme ontem.', 'Prefiro estudar do que sair.', 'Ela aspira o cargo de gerente.', 'Obedecemos às normas do edital.'], a: 3, e: 'Obedecer A. Correto: "assisti AO filme", "prefiro estudar A sair", "aspira AO cargo".' },
  { t: 'port', q: 'Assinale a alternativa com colocação pronominal CORRETA:', o: ['Me empresta a caneta.', 'Não diga-me isso.', 'Ninguém se lembrou da reunião.', 'Eles tinham chamado-me.'], a: 2, e: 'Pronome indefinido (ninguém) atrai o pronome: próclise. Não se inicia frase com pronome oblíquo; palavra negativa exige próclise ("Não me diga"); após particípio não se usa ênclise ("tinham-me chamado").' },
  { t: 'port', q: 'A mesóclise é empregada corretamente em:', o: ['Dir-se-ia que ele não estudou.', 'Não dir-se-ia nada.', 'Disse-se que ele estudou.', 'Ele dizer-se-á culpado.'], a: 0, e: 'Mesóclise: verbo no futuro do presente ou do pretérito, sem palavra atrativa. "Não" exige próclise.' },
  { t: 'port', q: 'Assinale a alternativa em que a vírgula está empregada INCORRETAMENTE:', o: ['Maria, venha cá.', 'O candidato, que estudou muito, passou.', 'Os alunos da turma, saíram cedo.', 'Comprei canetas, lápis e borrachas.'], a: 2, e: 'Nunca se separa o sujeito ("Os alunos da turma") do verbo por vírgula. As demais estão corretas: vocativo, oração adjetiva explicativa e enumeração.' },
  { t: 'port', q: 'Complete: "Não sei ___ ele faltou. Ele faltou ___ estava doente. Faltou por ___?"', o: ['porque / por que / quê', 'por que / porque / quê', 'porquê / porque / que', 'por que / porquê / quê'], a: 1, e: '"Por que" (pergunta indireta), "porque" (explicação), "por quê" (fim de frase, acentuado).' },
  { t: 'port', q: 'Assinale a alternativa CORRETA quanto ao uso de "mal/mau" e "há/a":', o: ['Ele é um mal funcionário; chegou há pouco.', 'Ele é um mau funcionário; chegou há pouco.', 'Ele é um mau funcionário; chegou a pouco.', 'Ele é um mal funcionário; chegou a pouco.'], a: 1, e: '"Mau" é adjetivo (antônimo de bom). "Há" indica tempo passado. "A" indica tempo futuro ou distância ("daqui a pouco").' },
  { t: 'port', q: 'Segundo o Novo Acordo Ortográfico, está CORRETAMENTE grafada a palavra:', o: ['idéia', 'assembléia', 'heróico', 'ideia'], a: 3, e: 'Paroxítonas com ditongo aberto "ei"/"oi" perderam o acento: ideia, assembleia, heroico, jiboia. Oxítonas mantêm: herói, papéis.' },
  { t: 'port', q: 'Em "Estudou muito, MAS não passou", a conjunção destacada estabelece relação de:', o: ['causa.', 'oposição (adversativa).', 'conclusão.', 'condição.'], a: 1, e: 'Mas, porém, contudo, todavia, entretanto: adversativas (oposição).' },
  { t: 'port', q: 'Em "EMBORA estivesse cansado, continuou estudando", a conjunção indica:', o: ['concessão.', 'causa.', 'finalidade.', 'tempo.'], a: 0, e: 'Embora, ainda que, mesmo que, apesar de que: concessivas. Causa: porque, visto que. Conclusão: portanto, logo.' },
  { t: 'port', q: 'Na frase "O coração dela é de pedra", a expressão "de pedra" foi empregada em sentido:', o: ['denotativo (próprio).', 'conotativo (figurado).', 'técnico.', 'literal.'], a: 1, e: 'Sentido figurado (conotação): o coração não é literalmente de pedra, mas insensível. Denotação é o sentido literal do dicionário.' },
  { t: 'port', q: 'O antônimo de "benevolente" é:', o: ['generoso.', 'bondoso.', 'malévolo.', 'complacente.'], a: 2, e: 'Benevolente = bondoso, generoso. Antônimo: malévolo, maldoso.' },
  { t: 'port', q: 'Em "Ele chegou cedo e saiu rapidamente", as palavras "cedo" e "rapidamente" são:', o: ['adjetivos.', 'advérbios.', 'substantivos.', 'conjunções.'], a: 1, e: 'Modificam o verbo indicando tempo e modo: advérbios (invariáveis).' },
  { t: 'port', q: 'Assinale a frase CORRETA quanto à concordância com sujeito posposto:', o: ['Chegou os alunos atrasados.', 'Chegaram os alunos atrasados.', 'Faltou dois candidatos.', 'Sobrou muitas vagas.'], a: 1, e: 'O verbo concorda com o sujeito mesmo quando este vem depois: "Chegaram os alunos", "Faltaram dois candidatos", "Sobraram muitas vagas".' },
  { t: 'port', q: 'Assinale a alternativa CORRETA:', o: ['Seguem anexo as cópias solicitadas.', 'Ela estava meia cansada.', 'Seguem anexas as cópias solicitadas.', 'Compramos meia dúzia de ovos e meio garrafa de água.'], a: 2, e: '"Anexo" é adjetivo e concorda com o substantivo (anexas as cópias). "Meio" como advérbio é invariável ("meio cansada"); como numeral concorda ("meia garrafa").' },
  { t: 'port', q: 'Em um texto, a informação que NÃO está explícita mas pode ser deduzida pelo leitor a partir das pistas do texto chama-se:', o: ['inferência.', 'paráfrase.', 'citação.', 'resumo.'], a: 0, e: 'Inferência: conclusão a partir de pistas. Questões do tipo "pode-se concluir que" exigem inferência; "segundo o texto" exige informação literal.' },
  { t: 'port', q: 'Todas as palavras proparoxítonas:', o: ['nunca são acentuadas.', 'são sempre acentuadas.', 'só são acentuadas se terminarem em vogal.', 'perderam o acento com o Novo Acordo.'], a: 1, e: 'Regra sem exceção: toda proparoxítona recebe acento (lâmpada, médico, público).' },
  { t: 'port', q: 'Assinale a alternativa em que a crase é FACULTATIVA:', o: ['Fui à escola.', 'Entreguei o livro a Maria.', 'Refiro-me à senhora.', 'Vou a Brasília.'], a: 1, e: 'Antes de nome próprio feminino de pessoa, a crase é facultativa ("a Maria" ou "à Maria"). Antes de "senhora" é obrigatória; "a Brasília" não tem crase (quem vai A Brasília volta DE Brasília, sem artigo).' },

  // ================= LEGISLAÇÃO MUNICIPAL =================
  { t: 'leg', q: 'NÃO é forma de provimento de cargo público:', o: ['nomeação.', 'reintegração.', 'exoneração.', 'aproveitamento.'], a: 2, e: 'Exoneração é forma de VACÂNCIA. Provimento na LC 146/2011 (art. 15): nomeação, promoção, reintegração, reversão, aproveitamento, readaptação, readmissão e recondução.' },
  { t: 'leg', q: 'O retorno à atividade do servidor aposentado chama-se:', o: ['reintegração.', 'reversão.', 'recondução.', 'readaptação.'], a: 1, e: 'Reversão: retorno do aposentado. Reintegração: retorno do demitido ilegalmente. Recondução: retorno ao cargo anterior. Readaptação: cargo compatível com limitação de saúde.' },
  { t: 'leg', q: 'A reinvestidura do servidor estável no cargo anteriormente ocupado, quando invalidada a sua demissão por decisão administrativa ou judicial, denomina-se:', o: ['reversão.', 'aproveitamento.', 'reintegração.', 'remoção.'], a: 2, e: 'Reintegração, com ressarcimento de todas as vantagens.' },
  { t: 'leg', q: 'A investidura do servidor em cargo de atribuições compatíveis com a limitação que tenha sofrido em sua capacidade física ou mental chama-se:', o: ['readaptação.', 'recondução.', 'reversão.', 'redistribuição.'], a: 0, e: 'Readaptação: forma de provimento por motivo de saúde, verificada em inspeção médica.' },
  { t: 'leg', q: 'São formas de VACÂNCIA do cargo público:', o: ['nomeação e posse.', 'exoneração, demissão, aposentadoria e falecimento.', 'remoção e redistribuição.', 'reversão e aproveitamento.'], a: 1, e: 'Na LC 146/2011 (art. 61) são exatamente estas quatro hipóteses. Na Lei 8.112 há ainda posse em outro cargo inacumulável, promoção e readaptação.' },
  { t: 'leg', q: 'Sobre exoneração e demissão, é CORRETO afirmar:', o: ['ambas são penalidades disciplinares.', 'a exoneração é penalidade; a demissão não.', 'a demissão é penalidade disciplinar; a exoneração não tem caráter punitivo (a pedido ou de ofício).', 'nenhuma delas gera vacância.'], a: 2, e: 'Exoneração: a pedido do servidor ou de ofício (ex.: não aprovação em estágio probatório). Demissão: sanção por infração grave.' },
  { t: 'leg', q: 'Segundo o edital do concurso (item 1.9), o servidor do município faz jus a:', o: ['licença-prêmio de 30 dias a cada 2 anos.', 'licença-prêmio de 90 dias a cada 5 anos, quinquênio de 5% e sexta-parte aos 20 anos.', 'sexta-parte aos 10 anos.', 'quinquênio de 10%.'], a: 1, e: 'Esses benefícios constam do edital e devem ser conferidos no texto do Estatuto (LC 146/2011).' },
  { t: 'leg', q: 'Pela Constituição Federal (art. 41), o servidor nomeado para cargo efetivo adquire estabilidade após:', o: ['2 anos de efetivo exercício.', '3 anos de efetivo exercício, com avaliação especial de desempenho.', '5 anos de efetivo exercício.', 'a posse.'], a: 1, e: 'Estabilidade após 3 anos de efetivo exercício, condicionada à avaliação especial de desempenho por comissão.' },
  { t: 'leg', q: 'As responsabilidades civil, penal e administrativa do servidor:', o: ['excluem-se mutuamente.', 'são independentes entre si e podem cumular-se.', 'dependem sempre de condenação penal prévia.', 'só se aplicam a servidores comissionados.'], a: 1, e: 'Independentes e cumuláveis. A absolvição penal por inexistência do fato ou negativa de autoria afasta a responsabilidade administrativa.' },
  { t: 'leg', q: 'Pelo item 13.16 do edital, a legislação cobrada na prova é a vigente até:', o: ['a data da prova (22/11/2026).', 'a data de publicação do edital (17/08/2026).', '31/12/2025.', 'a data da posse.'], a: 1, e: 'Alterações posteriores a 17/08/2026 não caem. Importante para a Lei Orgânica, que teve revisão discutida em 2026.' },
  { t: 'leg', q: 'São impostos de competência do MUNICÍPIO (CF, art. 156):', o: ['IPVA, ICMS e ITCMD.', 'IPTU, ISS e ITBI.', 'IR, IPI e IOF.', 'IPTU, IPVA e ISS.'], a: 1, e: 'Municipais: IPTU, ITBI e ISS. Estaduais: ICMS, IPVA, ITCMD. Federais: IR, IPI, IOF, II, IE, ITR.' },
  { t: 'leg', q: 'A Lei Orgânica do Município, segundo a CF (art. 29), é votada:', o: ['em turno único, por maioria simples.', 'em dois turnos, com interstício mínimo de 10 dias, e aprovada por 2/3 dos membros da Câmara, que a promulga.', 'pelo prefeito, por decreto.', 'pela Assembleia Legislativa do Estado.'], a: 1, e: 'Dois turnos, interstício de 10 dias, quórum de 2/3, promulgada pela própria Câmara.' },
  { t: 'leg', q: 'A fiscalização do Município é exercida pelo Poder Legislativo Municipal, mediante controle externo, com o auxílio:', o: ['do Ministério Público Federal.', 'do Tribunal de Contas do Estado (ou do Município, onde houver).', 'da Polícia Federal.', 'do Governador do Estado.'], a: 1, e: 'CF art. 31. O parecer prévio do Tribunal de Contas sobre as contas do prefeito só deixa de prevalecer por decisão de 2/3 dos membros da Câmara.' },
  { t: 'leg', q: 'O parecer prévio do Tribunal de Contas sobre as contas anuais do Prefeito só deixará de prevalecer por decisão de:', o: ['maioria simples da Câmara.', 'maioria absoluta da Câmara.', '2/3 dos membros da Câmara Municipal.', 'do Governador do Estado.'], a: 2, e: 'CF art. 31, §2º.' },
  { t: 'leg', q: 'Quanto à acumulação remunerada de cargos públicos (CF, art. 37, XVI), é permitida, havendo compatibilidade de horários:', o: ['a de dois cargos de técnico de contabilidade.', 'a de dois cargos de professor; a de um cargo de professor com outro técnico ou científico; a de dois cargos privativos de profissionais de saúde com profissões regulamentadas.', 'a de três cargos quaisquer.', 'nenhuma acumulação é permitida.'], a: 1, e: 'Regra: vedada a acumulação. Exceções taxativas da CF, sempre com compatibilidade de horários.' },
  { t: 'leg', q: 'Compete ao Município, nos termos da CF (art. 30):', o: ['legislar sobre direito civil e penal.', 'legislar sobre assuntos de interesse local e suplementar a legislação federal e estadual no que couber.', 'emitir moeda.', 'declarar guerra.'], a: 1, e: 'Competências municipais: interesse local, suplementar, instituir e arrecadar tributos de sua competência, organizar serviços públicos locais (transporte coletivo), etc.' },
  { t: 'leg', q: 'O mandato do Prefeito e dos Vereadores tem duração de:', o: ['2 anos.', '4 anos.', '5 anos.', '8 anos.'], a: 1, e: 'CF art. 29: mandato de 4 anos, eleição no primeiro domingo de outubro do ano anterior ao término do mandato.' },
  { t: 'leg', q: 'Entre os DEVERES típicos do servidor público previstos nos estatutos, inclui-se:', o: ['receber presentes de fornecedores.', 'exercer com zelo e dedicação as atribuições do cargo e ser leal às instituições.', 'retirar documentos da repartição sem autorização.', 'promover manifestação de apreço no recinto da repartição.'], a: 1, e: 'As demais alternativas são PROIBIÇÕES clássicas dos estatutos de servidores.' },
  { t: 'leg', q: 'As penalidades disciplinares normalmente previstas nos estatutos de servidores, em ordem crescente de gravidade, são:', o: ['demissão, suspensão e advertência.', 'advertência, suspensão e demissão.', 'multa, prisão e exoneração.', 'suspensão, advertência e demissão.'], a: 1, e: 'Advertência (escrita) → suspensão (até 90 dias) → demissão. A LC 146/2011 (art. 214) prevê seis penalidades: advertência, multa, suspensão, demissão, cassação de aposentadoria e destituição de cargo em comissão.' },
  { t: 'leg', q: 'A apuração de irregularidade no serviço público, quando a penalidade cabível for mais grave que advertência ou suspensão curta, deve ser feita mediante:', o: ['simples despacho do chefe imediato.', 'processo administrativo disciplinar (PAD), assegurados o contraditório e a ampla defesa.', 'inquérito policial.', 'decisão do Tribunal de Contas.'], a: 1, e: 'Sindicância: apuração preliminar ou penalidades leves. PAD: penalidades graves (demissão, suspensão longa), com contraditório e ampla defesa (CF art. 5º, LV).' },
].map((q, i) => ({ id: 'q' + i, ...q }));
